-- Whether a person is on hold: while held, their OPEN claims count in no live total (their own
-- claimed and due-total, the sheet's totals, a period's total); their SETTLED claims still count.
ALTER TABLE person ADD COLUMN held BOOLEAN DEFAULT FALSE NOT NULL;
# POST /api/sheets/{sheetId}/people/{personId}/hold — put the person on hold, or take them off it
# when held. While held their OPEN claims count in no live total; their SETTLED claims still do.
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.TogglePersonHold
  govern: [ transaction ]
  next: audit
