package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId,
            @PathVariable("personId") long personId, PersonRepository people,
            Out<Person> person) throws PersonNotFoundException {
        Person found = people.find(sheetId.trim(), personId);
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidPerson {
    public void handle(@Parameter InvalidPersonException ex,
            ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Takes a statement of the person: records their due-total now (the sum of the due of their claims that
 *  count live (OPEN ones of a person on hold do not), n/a ones skipped; n/a when their grade has no rate on the sheet's today and none of
 *  those claims keeps a settled or bound figure, or a live one at a grade no longer in force) on the sheet's today, and binds each counting claim
 *  to the figure under the due it shows now (its late charge is never bound); a claim that does not
 *  count live is unbound. */
public class TakeStatement {
    public void take(@Val Person person, PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        String floor = settings.floor(sheetId);
        Dues.Late late = settings.late(sheetId, today);
        List<Claim> own = claims.listOf(sheetId, person.getId());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int bound = 0;
        for (Claim c : own) {
            if (!person.countsLive(c)) {
                c.bind(false, null);
            } else {
                String grade = person.gradeOn(c.getDate());
                Rate rate = rates.find(sheetId, grade, LocalDate.parse(c.getDate()));
                String live = rate == null ? null : Dues.of(c.getAmount(), rate.pct(), floor, late.rounding(c.getRoundDate()));
